/**
 * Apply the catalogue generated by verify-systems.mjs to the database.
 *
 *   node --env-file=.env.local scripts/apply-verified.mjs <migration.sql>
 *
 * Split from the generator on purpose: the generator is a read-only probe
 * anyone can run and diff, and only this half needs the service-role key —
 * `bike_systems` refuses client writes by policy, exactly like climate_cache.
 *
 * It reads the VALUES out of the generated file rather than taking a second
 * route to the same data, so what lands in the database is what is committed
 * in the migration.
 */
import fs from "node:fs";
import { createClient } from "@supabase/supabase-js";

const file = process.argv[2];
if (!file) throw new Error("usage: apply-verified.mjs <migration.sql>");
const sql = fs.readFileSync(file, "utf8");

/* One tuple per line, as the generator writes them. */
const rows = [];
for (const line of sql.split("\n")) {
  const m = line.match(/^\s*\((.*)\)[,;]?\s*$/);
  if (!m) continue;
  const cells = [];
  let cur = "";
  let quoted = false;
  for (let i = 0; i < m[1].length; i++) {
    const ch = m[1][i];
    if (ch === "'") {
      if (quoted && m[1][i + 1] === "'") { cur += "'"; i++; }
      else quoted = !quoted;
    } else if (ch === "," && !quoted) { cells.push(cur.trim()); cur = ""; }
    else cur += ch;
  }
  cells.push(cur.trim());
  if (cells.length !== 11) continue;
  const [slug, name, city, region, country, status_url, information_url, lat, lon, station_count] = cells;
  rows.push({
    slug, name, city,
    region: region === "null" ? null : region,
    country: country === "null" ? null : country,
    status_url, information_url,
    lat: Number(lat), lon: Number(lon),
    station_count: Number(station_count),
    verified_at: new Date().toISOString(),
  });
}
console.log(`parsed ${rows.length} systems from ${file}`);

const db = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY,
  { auth: { persistSession: false, autoRefreshToken: false } },
);

/* Clear first, so a system that has stopped passing drops out of the picker
   even though its row stays for the stations that reference it. */
const cleared = await db
  .from("bike_systems")
  .update({ verified_at: null })
  .not("verified_at", "is", null);
if (cleared.error) throw new Error("clearing: " + cleared.error.message);

/* The existing row wins on slug: see the bike_systems_one_per_city index.
   PostgREST can only upsert on a real unique column, so a city already in the
   table is updated by city and only a genuinely new city is inserted. */
const { data: known, error: readErr } = await db
  .from("bike_systems")
  .select("slug, city");
if (readErr) throw new Error("reading: " + readErr.message);
const slugForCity = new Map(known.map((k) => [k.city.toLowerCase(), k.slug]));

let updated = 0;
let inserted = 0;
for (const row of rows) {
  const existing = slugForCity.get(row.city.toLowerCase());
  if (existing) {
    /* Everything but the slug: the row a trip already points at keeps its
       own, since registry System IDs are not stable between runs. */
    const rest = { ...row };
    delete rest.slug;
    const { error } = await db.from("bike_systems").update(rest).eq("slug", existing);
    if (error) throw new Error(`${row.city}: ${error.message}`);
    updated++;
  } else {
    const { error } = await db.from("bike_systems").insert(row);
    if (error) throw new Error(`${row.city}: ${error.message}`);
    inserted++;
  }
}
console.log(`updated ${updated}, inserted ${inserted}`);
